<script setup lang="ts">import {ref,onMounted} from 'vue';import {request} from '../api/client';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const rows=ref<any[]>([]),error=ref('');onMounted(async()=>{try{rows.value=await request('/audits')}catch(e){error.value=(e as Error).message}})</script><template><PageHeading index="06 / 审计记录" title="每次抽样决定，保留复核足迹。" note="记录写入路径、响应码和认证状态；不记录密码、Token或上传正文。仅管理员可查看。"/><Notice :message="error"/><div class="table-wrap"><table><thead><tr><th>时间 UTC</th><th>认证状态</th><th>方法</th><th>路径</th><th>响应</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.created_at}}</td><td>{{r.actor}}</td><td>{{r.method}}</td><td>{{r.path}}</td><td>{{r.status}}</td></tr></tbody></table></div></template>
